/* Originally generated by Payload; wrapped so an unreachable database returns
   503 instead of letting Payload's first connection attempt exit the process. */
import config from '@payload-config'
import '@payloadcms/next/css'
import {
  REST_DELETE,
  REST_GET,
  REST_OPTIONS,
  REST_PATCH,
  REST_POST,
  REST_PUT,
} from '@payloadcms/next/routes'
import { isDatabaseReachable } from '@/src/lib/db-health'

type RestHandler = (request: Request, args: { params: Promise<{ slug: string[] }> }) => Promise<Response>

function withDatabase(handler: RestHandler): RestHandler {
  return async (request, args) => {
    if (!(await isDatabaseReachable())) {
      return Response.json(
        { errors: [{ message: 'The database is temporarily unavailable. Please try again shortly.' }] },
        { status: 503, headers: { 'Retry-After': '15' } },
      )
    }
    return handler(request, args)
  }
}

export const GET = withDatabase(REST_GET(config))
export const POST = withDatabase(REST_POST(config))
export const DELETE = withDatabase(REST_DELETE(config))
export const PATCH = withDatabase(REST_PATCH(config))
export const PUT = withDatabase(REST_PUT(config))
export const OPTIONS = REST_OPTIONS(config)
